def IsMonoAP (c : Fin 9 → Bool) (a d : Fin 9) : Prop := a.val + 2 * d.val < 9 ∧ d.val > 0 ∧ c a = c ⟨a.val + d.val, by omega⟩ ∧ c a = c ⟨a.val + 2 * d.val, by omega⟩
def check (c : Fin 9 → Bool) : Bool := ∃ a d : Fin 9, decide (IsMonoAP c a d)
def allChecks : Bool := ∀ c : Fin 9 → Bool, check c
